(function() {
  if (window.__skpm_pm_wrapped) return;
  window.__skpm_pm_wrapped = true;

  window.onerror = function(msg, url, line) {
    try {
      document.body.style.background = '#ff4444';
      document.body.innerHTML = '<div style="color:white;padding:20px;font-family:monospace;font-size:13px;"><b>JS Error</b><br><br>' + String(msg).substring(0, 300) + '<br><br><i>line ' + line + '</i></div>';
    } catch(e) {}
    return false;
  };

  var _skpmPM = window.postMessage;
  var _nativePM = window.originalPostMessage || window.postMessage;

  window.postMessage = function(actionName) {
    if (actionName && typeof actionName === 'string') {
      return _skpmPM.apply(this, arguments);
    }
    if (_nativePM) {
      return _nativePM.apply(window, arguments);
    }
  };
})();
